package com.abluepoint.summer.sample.auditledger.application;

import java.time.Instant;
public record AuditQuery(String initiator,String actor,String effectiveSubject,String agentInstanceId,String toolId,String decision,String resultStatus,String invocationId,String eventType,Instant from,Instant to,String requestId,String traceId){
 public AuditQuery(String initiator,String actor,String effectiveSubject,String agentInstanceId,String toolId,String decision,String resultStatus,String invocationId,String eventType,Instant from,Instant to){
  this(initiator, actor, effectiveSubject, agentInstanceId, toolId, decision, resultStatus, invocationId, eventType, from, to, null, null);
 }
 public boolean matches(AuditEventView v){return (initiator==null||initiator.equals(v.initiator())||initiator.equals(detail(v,"initiator")))&&(actor==null||actor.equals(v.actor())||actor.equals(detail(v,"actor")))&&(effectiveSubject==null||effectiveSubject.equals(v.effectiveSubject())||effectiveSubject.equals(detail(v,"effectiveSubject")))&&(agentInstanceId==null||agentInstanceId.equals(v.agentInstanceId())||agentInstanceId.equals(detail(v,"agentInstanceId")))&&(toolId==null||toolId.equals(v.toolId())||toolId.equals(detail(v,"toolId")))&&(decision==null||decision.equals(v.decision())||decision.equals(detail(v,"decision")))&&(resultStatus==null||resultStatus.equals(detail(v,"resultStatus")))&&(invocationId==null||invocationId.equals(v.invocationId()))&&(eventType==null||eventType.equals(v.eventType()))&&(requestId==null||requestId.equals(v.requestId())||requestId.equals(detail(v,"requestId")))&&(traceId==null||traceId.equals(v.traceId())||traceId.equals(detail(v,"traceId")))&&(from==null||!v.occurredAt().isBefore(from))&&(to==null||!v.occurredAt().isAfter(to));}
 private static String detail(AuditEventView v, String key){ Object value=v.detail().get(key); return value == null ? null : String.valueOf(value); }
 public boolean matches(McpInvocationView v){return (initiator==null||initiator.equals(v.initiator()))&&(actor==null||actor.equals(v.actor()))&&(effectiveSubject==null||effectiveSubject.equals(v.effectiveSubject()))&&(agentInstanceId==null||agentInstanceId.equals(v.agentInstanceId()))&&(toolId==null||toolId.equals(v.toolId()))&&(decision==null||decision.equals(v.decision()))&&(invocationId==null||invocationId.equals(v.invocationId()))&&(resultStatus==null||resultStatus.equals(v.resultStatus()));}
}
